DROP VIEW "public"."round_summaries";--> statement-breakpoint
CREATE VIEW "public"."round_summaries" AS (select "rounds"."id", "rounds"."tournament_id", "rounds"."match_id", "seasons"."club_id", "rounds"."user_id", "rounds"."course_id", "rounds"."date", "rounds"."player_index_override", "course_tees"."rating", "course_tees"."slope", count("round_scores"."strokes") as "recorded_strokes_count", count("round_scores"."putts") as "recorded_putts_count", coalesce(sum("round_scores"."strokes"), 0)::int as "total_strokes", coalesce(sum("round_scores"."putts"), 0)::int as "total_putts", count("round_scores"."strokes") = 18 as "is_complete", case when count("round_scores"."strokes") = 18 then ((113.0 / "course_tees"."slope") * (sum("round_scores"."strokes") - "course_tees"."rating"))::double precision else null end as "score_differential" from "rounds" inner join "course_tees" on "rounds"."tee_id" = "course_tees"."id" left join "tournaments" on "rounds"."tournament_id" = "tournaments"."id" left join "seasons" on "tournaments"."season_id" = "seasons"."id" left join "round_scores" on "rounds"."id" = "round_scores"."round_id" group by "rounds"."id", "rounds"."tournament_id", "rounds"."match_id", "seasons"."club_id", "rounds"."user_id", "rounds"."course_id", "rounds"."date", "rounds"."player_index_override", "course_tees"."rating", "course_tees"."slope");